import xml.etree.ElementTree as ET
runs = [
    '<testsuite><testcase name="test_alloc"/><testcase name="test_dma"><failure message="timeout"/></testcase><testcase name="test_free"><failure message="bad pattern"/></testcase></testsuite>',
    '<testsuite><testcase name="test_alloc"/><testcase name="test_dma"/><testcase name="test_free"><failure message="bad pattern"/></testcase></testsuite>',
]
history = {}
for xml in runs:
    for tc in ET.fromstring(xml).iter("testcase"):
        history.setdefault(tc.get("name"), []).append(tc.find("failure") is None)
for name, res in history.items():
    tag = "불안정" if len(set(res)) > 1 else ("통과" if all(res) else "실패")
    print(name, res, tag)
# test_alloc [True, True] 통과
# test_dma [False, True] 불안정
# test_free [False, False] 실패
